function fewestMarbles(board: string, hand: string): number {
  const collapse = (s: string): string => {
    for (let changed = true; changed; ) {
      changed = false;
      for (let i = 0; i < s.length; ) {
        let j = i;
        while (j < s.length && s[j] === s[i]) j++;
        if (j - i >= 3) { s = s.slice(0, i) + s.slice(j); changed = true; break; }
        i = j;
      }
    }
    return s;
  };
  const start = hand.split("").sort().join("");
  const seen = new Set([board + "#" + start]);
  let level: [string, string][] = [[board, start]];
  for (let used = 0; level.length; used++) {
    const next: [string, string][] = [];
    for (const [row, h] of level) {
      if (row.length === 0) return used;
      for (let k = 0; k < h.length; k++) {
        if (k > 0 && h[k] === h[k - 1]) continue;
        const rest = h.slice(0, k) + h.slice(k + 1);
        for (let i = 0; i <= row.length; i++) {
          const nr = collapse(row.slice(0, i) + h[k] + row.slice(i));
          const key = nr + "#" + rest;
          if (!seen.has(key)) { seen.add(key); next.push([nr, rest]); }
        }
      }
    }
    level = next;
  }
  return -1;
}

