function fewestMarbles(board: string, hand: string): number {
  const collapse = (s: string): string => {
    for (let changed = true; changed; ) {
      changed = false;
      for (let i = 0; i < s.length; ) {
        let j = i;
        while (j < s.length && s[j] === s[i]) j++;
        if (j - i >= 3) { s = s.slice(0, i) + s.slice(j); changed = true; break; }
        i = j;
      }
    }
    return s;
  };
  const memo = new Map<string, number>();
  const solve = (row: string, h: string): number => {
    if (row.length === 0) return 0;
    if (h.length === 0) return Infinity;
    const key = row + "#" + h;
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    let best = Infinity;
    for (let k = 0; k < h.length; k++) {
      if (k > 0 && h[k] === h[k - 1]) continue;
      const c = h[k], rest = h.slice(0, k) + h.slice(k + 1);
      for (let i = 0; i < row.length; i++) {
        if (i > 0 && row[i - 1] === c) continue; // same as inserting one step earlier
        const sameColour = row[i] === c;
        const splitsPair = i > 0 && row[i - 1] === row[i] && row[i] !== c;
        if (!sameColour && !splitsPair) continue;
        best = Math.min(best, 1 + solve(collapse(row.slice(0, i) + c + row.slice(i)), rest));
      }
    }
    memo.set(key, best);
    return best;
  };
  const ans = solve(board, hand.split("").sort().join(""));
  return ans === Infinity ? -1 : ans;
}

